<?php
namespace mod_worksheetgrader\external;
use core_external\external_api; use core_external\external_function_parameters; use core_external\external_single_structure; use core_external\external_value;
final class save_team_layout extends external_api {
 public static function execute_parameters(): external_function_parameters { return new external_function_parameters(['sessionid'=>new external_value(PARAM_INT,'Session id'),'layoutjson'=>new external_value(PARAM_RAW,'Team layout JSON')]); }
 public static function execute(int $sessionid,string $layoutjson): array { global $DB,$USER;$params=self::validate_parameters(self::execute_parameters(),compact('sessionid','layoutjson'));$session=$DB->get_record('wsg_session',['id'=>$params['sessionid']],'*',MUST_EXIST);$activity=$DB->get_record('worksheetgrader',['id'=>$session->worksheetgraderid],'*',MUST_EXIST);$cm=get_coursemodule_from_instance('worksheetgrader',$activity->id,$activity->course,false,MUST_EXIST);$context=\context_module::instance($cm->id);self::validate_context($context);require_capability('mod/worksheetgrader:manageteams',$context);$layout=json_decode($params['layoutjson'],true);if(!is_array($layout))throw new \invalid_parameter_exception('Invalid layout JSON');\mod_worksheetgrader\service\team_manager::replace_layout($session->id,$layout,$USER->id);$canonical=\mod_worksheetgrader\service\team_manager::get_layout($session->id);$assigned=[];foreach($canonical as $t)foreach($t['members'] as $uid)$assigned[(int)$uid]=1;$studentcount=count(get_enrolled_users($context,'mod/worksheetgrader:submit',0,'u.id'));$unassigned=max(0,$studentcount-count($assigned));return ['ok'=>true,'teamcount'=>count($canonical),'assignedcount'=>count($assigned),'unassignedcount'=>$unassigned,'layoutjson'=>json_encode($canonical,JSON_UNESCAPED_UNICODE)]; }
 public static function execute_returns(): external_single_structure { return new external_single_structure(['ok'=>new external_value(PARAM_BOOL,'Saved'),'teamcount'=>new external_value(PARAM_INT,'Team count'),'assignedcount'=>new external_value(PARAM_INT,'Assigned students'),'unassignedcount'=>new external_value(PARAM_INT,'Unassigned students'),'layoutjson'=>new external_value(PARAM_RAW,'Canonical layout JSON')]); }
}
